function verifyActionPin(PDO $pdo): bool { $u=trim((string)($_POST['pin_username']??'')); $pin=(string)($_POST['action_pin']??''); $q=$pdo->prepare('SELECT id,username,pin_hash FROM admin_users WHERE username=?'); $q->execute([$u]); $a=$q->fetch(); if(!$a||!password_verify($pin,$a['pin_hash']))return false; $_SESSION['recipe_admin_id']=(int)$a['id']; $_SESSION['recipe_admin_username']=$a['username']; return true; }
function cleanIngredientItems(mixed $items): array|false { if(!is_array($items)||!count($items))return false; $clean=[]; foreach($items as $item){ if(!is_array($item))return false; $name=trim((string)($item['name']??'')); $quantity=$item['quantity']??null; $unit=trim((string)($item['unit']??'')); if($name===''||!is_numeric($quantity)||(float)$quantity<=0||$unit==='')return false; $row=['name'=>$name,'quantity'=>(float)$quantity,'unit'=>$unit]; foreach(['name_ta','name_th'] as $key){$v=trim((string)($item[$key]??''));if($v!=='')$row[$key]=$v;} $clean[]=$row; } return $clean; }
if(isset($_GET['logout'])) { unset($_SESSION['recipe_admin_authenticated'],$_SESSION['recipe_admin_id'],$_SESSION['recipe_admin_username']); goAdmin(); }
