 if($action==='create_admin' && $count===0){$u=trim((string)($_POST['username']??''));$pw=(string)($_POST['password']??'');$pin=(string)($_POST['pin']??'');if($u===''||strlen($pw)<10||strlen($pin)<4)$err='Username required; password needs 10+ characters and PIN 4+ characters.';else{$q=$pdo->prepare('INSERT INTO admin_users(username,password_hash,pin_hash) VALUES(?,?,?)');$q->execute([$u,password_hash($pw,PASSWORD_DEFAULT),password_hash($pin,PASSWORD_DEFAULT)]);$msg='Admin created. Sign in to continue.';$count=1;}}
 elseif($action==='login'){$u=trim((string)($_POST['username']??''));$pw=(string)($_POST['password']??'');$pin=(string)($_POST['pin']??'');$q=$pdo->prepare('SELECT * FROM admin_users WHERE username=?');$q->execute([$u]);$a=$q->fetch();if($a&&password_verify($pw,$a['password_hash'])&&password_verify($pin,$a['pin_hash'])){session_regenerate_id(true);$_SESSION['recipe_admin_authenticated']=true;$_SESSION['recipe_admin_id']=(int)$a['id'];$_SESSION['recipe_admin_username']=$a['username'];$logged=true;$msg='Welcome to Admin Dashboard.';}else $err='Username, password or PIN is incorrect.';}
 elseif($logged && $action==='add_ingredient_inline'){$lang=(string)($_POST['language_code']??'en');$name=trim((string)($_POST['new_ingredient']??''));if(!in_array($lang,['en','ta','th'],true)||$name==='')$err='Choose language and enter an ingredient.';else{try{$q=$pdo->prepare('INSERT INTO ingredients_master(name_en,name_ta,name_th,language_code) VALUES(?,?,?,?)');$q->execute([$name,'','',$lang]);$msg='Ingredient added. It is now available in the dropdown.';}catch(PDOException $e){$err='This ingredient already exists for the selected language.';}}}
 elseif($logged && $action==='add_unit_inline'){$name=trim((string)($_POST['unit_name']??''));$symbol=trim((string)($_POST['unit_symbol']??''));$type=(string)($_POST['unit_type']??'other');if($name===''||$symbol===''||!in_array($type,['weight','volume','count','other'],true))$err='Enter valid unit details.';else{try{$q=$pdo->prepare('INSERT INTO units_master(unit_name,unit_symbol,unit_type,base_unit) VALUES(?,?,?,?)');$q->execute([$name,$symbol,$type,$symbol]);$msg='Unit added and available in the dropdown.';}catch(PDOException $e){$err='That unit symbol already exists.';}}}
 elseif($logged && in_array($action,['view','edit','delete','save_edit'],true)){
  if(!verifyActionPin($pdo))$err='PIN verification failed. No action was performed.';else{$id=filter_var($_POST['recipe_id']??null,FILTER_VALIDATE_INT);if(!$id)$err='Invalid recipe ID.';elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM recipes WHERE id=?');$q->execute([$id]);$msg=$q->rowCount()?'Recipe deleted.':'Recipe not found.';}elseif($action==='view'||$action==='edit'){$q=$pdo->prepare('SELECT * FROM recipes WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)$err='Recipe not found.';elseif($action==='view')$view=$r;else $edit=$r;}else{$name=trim((string)($_POST['recipe_name']??''));$lang=(string)($_POST['recipe_language']??'en');$items=json_decode((string)($_POST['ingredients_json']??'[]'),true);$method=trim((string)($_POST['preparation_method']??''));$yield=(float)($_POST['base_yield']??1);$unit=trim((string)($_POST['base_unit']??'g'));$image=trim((string)($_POST['image_url']??''));if($name===''||!in_array($lang,['en','ta','th'],true)||!is_array($items)||!count($items)||$method===''||$yield<=0||!in_array(strtolower($unit),['g','kg','ml','litre','liter','l'],true))$err='Complete recipe name, valid ingredients, preparation method and a weight/volume yield (g, kg, ml or litre).';else{$items=cleanIngredientItems($items);if($items===false){$err='Each ingredient must have a name, positive numeric quantity and unit.';}else{$json=json_encode($items,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$q=$pdo->prepare('UPDATE recipes SET recipe_name=?,recipe_language=?,ingredients=?,preparation_method=?,base_yield=?,base_unit=?,image_url=? WHERE id=?');$q->execute([$name,$lang,$json,$method,$yield,$unit,$image,$id]);$msg='Recipe updated successfully.';}}}}}
 elseif($logged && $action==='add_recipe'){$name=trim((string)($_POST['recipe_name']??''));$lang=(string)($_POST['recipe_language']??'en');$items=json_decode((string)($_POST['ingredients_json']??'[]'),true);$method=trim((string)($_POST['preparation_method']??''));$yield=(float)($_POST['base_yield']??1);$unit=trim((string)($_POST['base_unit']??'g'));$image=trim((string)($_POST['image_url']??''));if($name===''||!in_array($lang,['en','ta','th'],true)||!is_array($items)||!count($items)||$method===''||$yield<=0||!in_array(strtolower($unit),['g','kg','ml','litre','liter','l'],true))$err='Complete recipe name, valid ingredients, preparation method and a weight/volume yield (g, kg, ml or litre).';else{$items=cleanIngredientItems($items);if($items===false){$err='Each ingredient must have a name, positive numeric quantity and unit.';}else{$json=json_encode($items,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$q=$pdo->prepare('INSERT INTO recipes(recipe_name,recipe_language,ingredients,preparation_method,base_yield,base_unit,image_url) VALUES(?,?,?,?,?,?,?)');$q->execute([$name,$lang,$json,$method,$yield,$unit,$image]);$msg='Recipe saved successfully!';}}}
}
