tre','liter','l'],true))continue;?><option value="<?=h($u['unit_symbol'])?>" <?=$u['unit_symbol']==='g'?'selected':''?>><?=h($u['unit_name'].' ('.$u['unit_symbol'].')')?></option><?php endforeach;?></select></div></div><p class="muted">Important: enter the total quantity this original ingredient list makes (for example, if these ingredients make 100 g, enter 100 and choose g). The calculator scales ingredient quantities from this base yield. Ingredient units such as tsp and tbsp are preserved.</p><details class="card" style="background:#f9fcf7;box-shadow:none"><summary style="font-weight:750;cursor:pointer;color:var(--green)">Unit not listed? Add a new unit</summary><div class="grid"><div class="field"><label>Unit name</label><input id="newUnitName" placeholder="e.g. handful"></div><div class="field"><label>Unit symbol</label><input id="newUnitSymbol" placeholder="e.g. handful"></div><div class="field"><label>Unit category</label><select id="newUnitType"><option value="weight">Weight</option><option value="volume">Volume</option><option value="count">Count</option><option value="other">Other</option></select></div></div><button class="btn light" id="saveUnit" type="button">Save unit to dropdown</button></details><div class="field"><label>5. Preparation method *</label><textarea name="preparation_method" required placeholder="Write the preparation steps in the selected language"></textarea></div><button class="btn">💾 Save Recipe</button></form></section>
