<script>
const ingredientData=<?=json_encode($ingredientData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let unitData=<?=json_encode($units,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const unitChoices=()=>unitData.map(u=>`<option value="${escapeHtml(u.unit_symbol)}">${escapeHtml(u.unit_name)} (${escapeHtml(u.unit_symbol)})</option>`).join('');function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function addIngredientRow(containerId,languageId,initial=null){const container=document.getElementById(containerId),lang=document.getElementById(languageId).value;if(!lang){alert('Please choose recipe language first.');return;}const list=[...(ingredientData[lang]||[])];if(initial&&initial.name&&!list.includes(initial.name))list.unshift(initial.name);const options=list.map(n=>`<option ${initial&&initial.name===n?'selected':''} value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join('');const row=document.createElement('div');row.className='ingredientRow';row.innerHTML=`<div class="field ingredient"><label>Ingredient</label><select class="ingredientName" required><option value="">Choose ingredient</option>${options}</select></div><div class="field"><label>Quantity</label><input class="ingredientQty" type="number" min="0.001" step="any" required placeholder="100" value="${initial?escapeHtml(initial.quantity):''}"></div><div class="field"><label>Unit</label><select class="ingredientUnit" required>${unitChoices()}</select></div><button class="btn danger removeRow" type="button">Remove</button>`;if(initial&&initial.unit)row.querySelector('.ingredientUnit').value=initial.unit;row.querySelector('.removeRow').onclick=()=>row.remove();container.appendChild(row);}
const lang=document.getElementById('recipeLanguage');lang?.addEventListener('change',()=>{const rows=document.getElementById('ingredientRows');rows.innerHTML='';if(lang.value){document.getElementById('addIngredientRow').disabled=false;addIngredientRow('ingredientRows','recipeLanguage');}else{document.getElementById('addIngredientRow').disabled=true;rows.innerHTML='<p class="muted">Select a language first to choose ingredients.</p>';}});document.getElementById('addIngredientRow')?.addEventListener('click',()=>addIngredientRow('ingredientRows','recipeLanguage'));
function makeIngredientsJson(rowsId,targetId){const items=[];let valid=true;document.querySelectorAll('#'+rowsId+' .ingredientRow').forEach(row=>{const name=row.querySelector('.ingredientName').value,quantity=parseFloat(row.querySelector('.ingredientQty').value),unit=row.querySelector('.ingredientUnit').value;if(!name||!Number.isFinite(quantity)||quantity<=0||!unit)valid=false;else items.push({name,quantity,unit});});if(!valid||!items.length){alert('Please complete every ingredient row, or remove any empty row.');return false;}document.getElementById(targetId).value=JSON.stringify(items);return true;}
document.getElementById('recipeForm')?.addEventListener('submit',e=>{if(!makeIngredientsJson('ingredientRows','ingredientsJson'))e.preventDefault();});
// Preserve the in-progress recipe while saving a new ingredient or unit.
const draftKey='smartRecipeHub.addRecipeDraft.v1';
function saveRecipeDraft(preferredIngredient=''){
 const form=document.getElementById('recipeForm'); if(!form)return;
 const rows=[]; document.querySelectorAll('#ingredientRows .ingredientRow').forEach(row=>rows.push({name:row.querySelector('.ingredientName')?.value||'',quantity:row.querySelector('.ingredientQty')?.value||'',unit:row.querySelector('.ingredientUnit')?.value||''}));
 const data={language:document.getElementById('recipeLanguage')?.value||'',name:form.querySelector('[name="recipe_name"]')?.value||'',yield:form.querySelector('[name="base_yield"]')?.value||'1',baseUnit:form.querySelector('[name="base_unit"]')?.value||'g',method:form.querySelector('[name="preparation_method"]')?.value||'',rows,preferredIngredient};
 sessionStorage.setItem(draftKey,JSON.stringify(data));
}
function restoreRecipeDraft(){
 const form=document.getElementById('recipeForm'); if(!form)return;
 let d; try{d=JSON.parse(sessionStorage.getItem(draftKey)||'null')}catch(e){d=null} if(!d)return;
 const language=document.getElementById('recipeLanguage'); language.value=d.language||'';
 form.querySelector('[name="recipe_name"]').value=d.name||'';
 form.querySelector('[name="base_yield"]').value=d.yield||'1';
 form.querySelector('[name="base_unit"]').value=d.baseUnit||'g';
 form.querySelector('[name="preparation_method"]').value=d.method||'';
 const rows=document.getElementById('ingredientRows'); rows.innerHTML='';
 if(language.value){document.getElementById('addIngredientRow').disabled=false;const savedRows=(d.rows&&d.rows.length)?d.rows:[{}];savedRows.forEach((item,index)=>{if(d.preferredIngredient && index===savedRows.length-1)item={...item,name:d.preferredIngredient};addIngredientRow('ingredientRows','recipeLanguage',item.name||item.quantity||item.unit?item:null);const row=rows.lastElementChild;if(row){if(item.name)row.querySelector('.ingredientName').value=item.name;if(item.quantity!=='')row.querySelector('.ingredientQty').value=item.quantity;if(item.unit)row.querySelector('.ingredientUnit').value=item.unit;}});}
 sessionStorage.removeItem(draftKey);
}
document.getElementById('saveIngredient')?.addEventListener('click',()=>{const language=lang.value,name=document.getElementById('newIngredientName').value.trim();if(!language){alert('Select recipe language first.');return;}if(!name){alert('Type an ingredient name first.');return;}saveRecipeDraft(name);const f=document.createElement('form');f.method='post';f.innerHTML=`<?=str_replace('`','\\`',csrf_field())?><input type="hidden" name="action" value="add_ingredient_inline"><input type="hidden" name="language_code" value="${escapeHtml(language)}"><input type="hidden" name="new_ingredient" value="${escapeHtml(name)}">`;document.body.appendChild(f);f.submit();});
document.getElementById('saveUnit')?.addEventListener('click',()=>{const name=document.getElementById('newUnitName').value.trim(),symbol=document.getElementById('newUnitSymbol').value.trim(),type=document.getElementById('newUnitType').value;if(!name||!symbol){alert('Enter unit name and symbol.');return;}saveRecipeDraft();const f=document.createElement('form');f.method='post';f.innerHTML=`<?=str_replace('`','\\`',csrf_field())?><input type="hidden" name="action" value="add_unit_inline"><input type="hidden" name="unit_name" value="${escapeHtml(name)}"><input type="hidden" name="unit_symbol" value="${escapeHtml(symbol)}"><input type="hidden" name="unit_type" value="${escapeHtml(type)}">`;document.body.appendChild(f);f.submit();});
restoreRecipeDraft();
function openPin(action,id,name){if(action==='delete'&&!confirm(`Delete “${name}”? This cannot be undone.`))return;document.getElementById('pinAction').value=action;document.getElementById('pinRecipeId').value=id;document.getElementById('pinTitle').textContent=action[0].toUpperCase()+action.slice(1)+' recipe';document.getElementById('pinDescription').textContent=`Enter admin username and PIN to ${action} “${name}”.`;document.getElementById('pinSubmit').textContent=action==='delete'?'Verify & delete':'Verify & '+action;document.getElementById('pinDialog').showModal();}
const editItems=<?=json_encode($editItems,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;if(document.getElementById('editRows')){for(const i of editItems)addIngredientRow('editRows','editLanguage',i);if(!editItems.length)addIngredientRow('editRows','editLanguage');document.getElementById('editForm').addEventListener('submit',e=>{if(!makeIngredientsJson('editRows','editJson'))e.preventDefault();});}
</script></body></html>
